```
class AppBundleLocaleChangesDetector : Detector(), SourceCodeScanner, GradleScanner {
    companion object {
        val ISSUE = Issue.create(
            id = "AppBundleLocaleChanges",
            briefDescription = "App Bundle handling of runtime locale changes",
            explanation = "...",
            category = Category.CORRECTNESS,
            priority = 5,
            severity = Severity.WARNING,
            implementation = Implementation(AppBundleLocaleChangesDetector::class.java, Scope.GRADLE_SCOPE, Scope.JAVA_FILE_SCOPE)
        )
    }

    private val localeChangeCalls = mutableListOf<Pair<JavaContext, UElement>>()
    private var languageSplitEnabled = true
    private var hasPlayCore = false

    override fun getApplicableUastTypes(): List<Class<out UElement>>? = listOf(UCallExpression::class.java)
    override fun createUastHandler(context: JavaContext): UElementHandler = object : UElementHandler() {
        override fun visitCallExpression(node: UCallExpression) {
            val method = node.resolve() ?: return
            val name = method.name
            val className = method.containingClass?.qualifiedName
            if ((className == "java.util.Locale" && name == "setDefault")
                || (className == "android.content.res.Resources" && name == "updateConfiguration")
                || (className == "android.content.res.Configuration" && (name == "setLocale" || name == "setLayoutDirection"))) {
                localeChangeCalls.add(context to node)
            }
        }
    }

    override fun checkDslProperty(... ) { ... }

    override fun afterCheckRootProject(context: Context) {
        if (languageSplitEnabled && !hasPlayCore && localeChangeCalls.isNotEmpty()) {
            for ((ctx, node) in localeChangeCalls) {
                ctx.report(ISSUE, node, ctx.getLocation(node), "message")
            }
        }
    }
}
```

